def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    ratio = np.where(valid, item / remaining, 0)
    return np.where(valid, -ratio, -np.inf)
